'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  aiMethods, caseMethods, caseStatus, emptyMonth, getStatistics, rankingIsCurrent,
  resultFor, validEvaluation,
  type DocumentEvaluation, type EvaluationAction, type EvaluationCase, type EvaluationState,
  type EvaluationUser, type OperationMonth, type RankValue, type Role, type SelectionRow,
} from '@/app/lib/evaluation';
import PdfDownloadButton from '@/app/components/pdf-download';
import { exportWorkbook } from '@/app/lib/export-workbook';
import './evaluation.css';

type ActionHandler = (action: EvaluationAction, message?: string) => Promise<boolean>;
type Shared = { state: EvaluationState; month: OperationMonth; save: ActionHandler; busy: boolean; dirty: (value: boolean) => void; hasUnsaved?: boolean };
type View = 'review' | 'ai' | 'stats' | 'settings';
const percent = (value: number | null) => value === null ? '—' : `${(value * 100).toFixed(1)}%`;
const normalized = (value: string) => value.replace(/[\s\-.,]/g, '').toUpperCase();
const numberLabel = (value: string) => { const digits = value.replace(/\D/g, ''); return digits.length === 13 ? `${digits.slice(0, 2)}-${digits.slice(2, 6)}-${digits.slice(6)}` : value; };
const monthLabel = (value: string) => `${value.slice(0, 4)}년 ${Number(value.slice(5))}월`;
const roleLabels: Record<Role, string> = { admin: '관리자', examiner: '심사관', ai: 'AI 담당자' };

function Badge({ children, color = '' }: { children: React.ReactNode; color?: string }) { return <span className={`ev-badge ${color}`}>{children}</span>; }
function Empty({ title, children }: { title: string; children?: React.ReactNode }) { return <div className="ev-empty"><div className="ev-empty-icon">▤</div><h3>{title}</h3>{children}</div>; }
function Status({ state, item }: { state: EvaluationState; item: EvaluationCase }) { const status = caseStatus(state, item); return <><Badge color={status.inputComplete ? 'green' : ''}>{status.inputComplete ? '입력 완료' : '대기 중'}</Badge><Badge color={status.complete ? 'green' : status.stale ? 'orange' : ''}>{status.evaluationStatus}</Badge></>; }
function Stat({ label, value, unit = '건', note, accent = false }: { label: string; value: string | number; unit?: string; note?: string; accent?: boolean }) { return <div className={`ev-stat ${accent ? 'accent' : ''}`}><div className="ev-stat-label">{label}<span>↗</span></div><div className="ev-stat-value">{value}<small>{unit}</small></div><div className="ev-stat-foot">{note || '\u00a0'}</div></div>; }
function Panel({ title, description, action, children }: { title: string; description?: string; action?: React.ReactNode; children: React.ReactNode }) { return <section className="ev-panel"><div className="ev-panel-head"><div><h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</div>{children}</section>; }
function CaseResource({ item, demo }: { item: EvaluationCase; demo: boolean }) { return <div className="ev-resource"><div><strong>검색을 시작하기 전, 출원 전문부터 준비하세요.</strong><p>{demo ? '가상 검증 자료의 출원번호입니다. 실제 PDF는 별도 원문 검색에서 확인하세요.' : '공개공보 PDF를 내려받아 외부 AI 도구의 검색 자료로 사용할 수 있습니다.'}</p></div><div className="ev-actions">{!demo && <><PdfDownloadButton applicationNumber={item.applicationNumber} label="↓ 공개 전문 PDF" /><PdfDownloadButton applicationNumber={item.applicationNumber} kind="registration" label="↓ 등록 전문 PDF" /></>}<a className="ev-button" href={`/patent?applicationNumber=${encodeURIComponent(item.applicationNumber)}`}>사건 상세 ↗</a></div></div>; }

export default function EvaluationWorkspace({ admin = false }: { admin?: boolean }) {
  const [state, setState] = useState<EvaluationState | null>(null);
  const [revision, setRevision] = useState(0);
  const [userId, setUserId] = useState('');
  const [loginUserId, setLoginUserId] = useState('');
  const [monthId, setMonthId] = useState('');
  const [view, setView] = useState<View>(admin ? 'stats' : 'review');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [loadSerial, setLoadSerial] = useState(0);
  const loadGeneration = useRef(0);
  const load = useCallback(async (selectedUser = userId) => {
    const requestId = ++loadGeneration.current;
    setLoading(true); setError('');
    try {
      const response = await fetch(`/api/evaluation?${admin ? 'admin=1' : `userId=${encodeURIComponent(selectedUser)}`}`, { cache: 'no-store' });
      const payload = await response.json() as { state: EvaluationState; revision: number; error?: string; warnings?: string[] };
      if (!response.ok) throw new Error(payload.error || '업무 자료를 불러오지 못했습니다.');
      if (requestId !== loadGeneration.current) return;
      setState(payload.state); setRevision(payload.revision); setLoadSerial((value) => value + 1);
      setMonthId((previous) => payload.state.months.some((month: OperationMonth) => month.id === previous) ? previous : payload.state.months.at(-1)?.id || '');
    } catch (reason) { setError(reason instanceof Error ? reason.message : '업무 자료를 불러오지 못했습니다.'); }
    finally { if (requestId === loadGeneration.current) setLoading(false); }
  }, [admin, userId]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => {
    const leave = (event: BeforeUnloadEvent) => { if (dirty) { event.preventDefault(); event.returnValue = ''; } };
    window.addEventListener('beforeunload', leave);
    const click = (event: MouseEvent) => {
      const link = (event.target as HTMLElement).closest('a[href]');
      if (dirty && link && !link.hasAttribute('target') && !window.confirm('저장하지 않은 내용이 있습니다. 이동하시겠습니까?')) event.preventDefault();
    };
    document.addEventListener('click', click);
    return () => { window.removeEventListener('beforeunload', leave); document.removeEventListener('click', click); };
  }, [dirty]);
  function navigate(action: () => void) { if (!dirty || window.confirm('저장하지 않은 내용이 있습니다. 이동하시겠습니까?')) { setDirty(false); setNotice(''); setError(''); action(); } }
  const save: ActionHandler = async (action, message = '저장했습니다.') => {
    setBusy(true); setError(''); setNotice('');
    try {
      const response = await fetch('/api/evaluation', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ revision, actor: admin ? { admin: true } : { userId }, action }) });
      const payload = await response.json() as { state: EvaluationState; revision: number; error?: string; warnings?: string[] };
      if (!response.ok) throw new Error(`${payload.error || '저장하지 못했습니다.'}${response.status === 409 ? ' 입력 내용은 유지됩니다. 최신 자료를 확인한 뒤 다시 저장해 주세요.' : ''}`);
      setState(payload.state); setRevision(payload.revision); setDirty(false); setNotice([message, ...(payload.warnings || [])].join(' ')); return true;
    } catch (reason) { setError(reason instanceof Error ? reason.message : '저장하지 못했습니다. 입력 내용은 유지됩니다.'); return false; }
    finally { setBusy(false); }
  };
  const user = state?.users.find((candidate) => candidate.id === userId);
  const month = state?.months.find((candidate) => candidate.id === monthId);
  const title = view === 'stats' ? '통계·현황' : view === 'settings' ? '운영 관리' : view === 'ai' ? 'AI 검색 결과 입력' : '내 심사 업무';
  const loggedIn = admin || Boolean(user);
  return <div className="ev"><div className="ev-shell">
    <aside className="ev-sidebar"><a className="ev-brand" href="/"><span className="ev-brand-mark">S</span><span><strong>심사데스크</strong><small>PRIOR ART REVIEW WORKSPACE</small></span></a>
      <div className="ev-side-label">WORKSPACE</div><nav aria-label="주요 메뉴">
        {admin ? <><button className={`ev-nav ${view === 'stats' ? 'active' : ''}`} onClick={() => navigate(() => setView('stats'))}><span>▦</span>통계·현황</button><button className={`ev-nav ${view === 'settings' ? 'active' : ''}`} onClick={() => navigate(() => setView('settings'))}><span>⚙</span>운영 관리</button></> : <><button className={`ev-nav ${view === 'review' ? 'active' : ''}`} onClick={() => navigate(() => setView('review'))}><span>▤</span>내 심사 업무</button>{user?.roles.includes('ai') && <button className={`ev-nav ${view === 'ai' ? 'active' : ''}`} onClick={() => navigate(() => setView('ai'))}><span>⌕</span>AI 담당 업무</button>}</>}
        <a className="ev-nav" href="/documents"><span>⇩</span>전문 PDF 모으기 ↗</a><a className="ev-nav" href="/patent"><span>▧</span>키프리스 원문 검색 ↗</a>
      </nav><div className="ev-side-bottom"><div className="ev-connection"><span className="ev-dot" />KIPRIS Plus 연동</div><p className="ev-side-note">출원 원문에서 검색 결과 평가까지<br />한곳에서 이어지는 심사 업무</p>{(admin || !user) && <a className="ev-nav" href={admin ? '/' : '/admin'}><span>↗</span>{admin ? '일반사용자 화면' : '관리자용 진입점'}</a>}</div>
    </aside>
    <main className="ev-main"><header className="ev-topbar"><div className="ev-breadcrumb">심사데스크 <span> / </span><b>{loggedIn ? title : '업무 시작'}</b></div><div className="ev-top-actions">{admin ? <Badge>관리자용 화면</Badge> : user ? <><div className="ev-top-user"><span className="ev-avatar">{user.name.slice(0, 1)}</span><span>{user.division} · <b>{user.name}</b></span></div><button className="ev-button link" onClick={() => navigate(() => { setUserId(''); setView('review'); })}>사용자 변경</button></> : <span className="ev-muted">AI 검색 결과 평가 시스템</span>}<button className="ev-button tiny" disabled={loading || busy} onClick={() => navigate(() => { void load(); })} aria-label="최신 자료 새로고침">↻ 새로고침</button></div></header>
      <div className="ev-content">{error && <div className="ev-alert" role="alert">{error}</div>}{notice && <div className="ev-alert success" role="status">{notice}</div>}
        {loading && !state ? <Empty title="업무 자료를 불러오고 있습니다." /> : !state ? <Empty title="자료에 연결할 수 없습니다."><button className="ev-button" onClick={() => void load()}>다시 시도</button></Empty> : !loggedIn ? <div className="ev-login"><div className="ev-login-intro"><div><div className="ev-eyebrow">AI SEARCH · HUMAN REVIEW</div><h1>검색의 시작부터<br />평가의 마무리까지.</h1><p>심사관이 선정한 출원의 전문을 준비하고, AI가 찾은 문헌을 함께 검토합니다. 본인을 선택해 월별 업무를 이어가세요.</p></div><div className="ev-login-art" aria-hidden="true"><div className="ev-paper" /><div className="ev-paper" /><span style={{ color: '#6fa895', fontSize: 27 }}>→</span></div></div><div className="ev-grid2"><Panel title="내 업무 시작하기" description="심사과와 이름을 확인해 본인을 선택하세요."><div className="ev-panel-body"><label>심사과 - 이름<select value={loginUserId} onChange={(event) => setLoginUserId(event.target.value)}><option value="">사용자를 선택하세요</option>{state.users.filter((candidate) => candidate.active).map((candidate) => <option value={candidate.id} key={candidate.id}>{candidate.division || '소속 미지정'} - {candidate.name}</option>)}</select></label><div className="ev-actions end"><button className="ev-button primary" disabled={!loginUserId} onClick={() => { setUserId(loginUserId); setView('review'); }}>업무 시작 →</button></div>{!state.users.length && <p className="ev-muted" style={{ marginTop: 13 }}>등록된 사용자가 없습니다. <a href="/admin" style={{ color: '#087f78' }}>관리자 화면</a>에서 사용자와 월별 배정을 먼저 설정하세요.</p>}</div></Panel><Panel title="이렇게 진행합니다"><div className="ev-panel-body" style={{ paddingTop: 4 }}>{[['01', '평가 대상 출원 선정', '출원번호를 등록하고 해당 월의 대상을 확정합니다.'], ['02', '전문 준비 · AI 검색 결과 입력', '출원 PDF를 받아 검색하고 문헌번호만 등록합니다.'], ['03', '문헌 평가 · 조사 방식 비교', '점수와 인용여부, 조사 방식별 품질 순위를 기록합니다.']].map(([step, name, text]) => <div className="ev-step" key={step}><span className="ev-step-number">{step}</span><div><h3>{name}</h3><p>{text}</p></div></div>)}</div></Panel></div><p className="ev-login-foot">사용자 선택은 업무 작성자를 정하는 간편 로그인입니다.</p></div> : <>
          <div className="ev-page-heading"><div><p className="ev-eyebrow">{admin ? 'OPERATIONS & INSIGHTS' : view === 'ai' ? 'AI SEARCH WORKSPACE' : 'MY REVIEW WORKSPACE'}</p><h1>{title}</h1><p className="ev-lead">{admin ? view === 'stats' ? '운영월별 입력과 평가 진행을 확인하고 같은 기준으로 취합합니다.' : '참여자, 조사 방식과 월별 담당 업무를 설정합니다.' : view === 'ai' ? '담당 출원의 전문을 준비하고, 외부 AI 도구에서 찾은 문헌을 등록하세요.' : '대상을 선정하고, 공개된 AI 검색 결과를 검토하세요.'}</p></div><div className="ev-month"><select aria-label="운영월" value={monthId} onChange={(event) => navigate(() => setMonthId(event.target.value))}>{state.months.map((candidate) => <option key={candidate.id} value={candidate.id}>{monthLabel(candidate.id)}</option>)}</select><Badge color={month?.closed ? 'orange' : 'green'}>{month?.closed ? '마감' : '운영 중'}</Badge></div></div>
          {state.isDemo && <div className="ev-notice warning">가상 검증 자료입니다. 출원·문헌번호와 사용자, 평가 실적은 실제 자료가 아닙니다.</div>}
          {month?.closed && <div className="ev-notice warning">이 운영월은 마감되었습니다. 자료 조회와 다운로드가 가능하며, 수정은 관리자 재개방 후 가능합니다.</div>}
          {month && (view === 'stats' && admin ? <AdminStats key={monthId} state={state} month={month} save={save} busy={busy} dirty={setDirty} notify={setNotice} /> : view === 'settings' && admin ? <AdminSettings key={monthId} state={state} month={month} save={save} busy={busy} dirty={setDirty} hasUnsaved={dirty} selectMonth={setMonthId} /> : user && view === 'ai' && user.roles.includes('ai') ? <AIWorkspace key={`${userId}:${monthId}:${loadSerial}`} state={state} month={month} save={save} busy={busy} dirty={setDirty} user={user} notify={setNotice} /> : user ? <ReviewWorkspace key={`${userId}:${monthId}:${loadSerial}`} state={state} month={month} save={save} busy={busy} dirty={setDirty} user={user} notify={setNotice} /> : null)}
        </>}
      </div></main>
  </div></div>;
}

function ReviewWorkspace(props: Shared & { user: EvaluationUser; notify: (text: string) => void }) {
  const { state, month, user, save, busy, dirty, notify } = props;
  const [selectedId, setSelectedId] = useState('');
  const [unsaved, setUnsaved] = useState(false);
  const cases = state.cases.filter((item) => item.monthId === month.id && item.examinerId === user.id && item.status === 'confirmed');
  const selected = cases.find((item) => item.id === selectedId) || cases[0];
  const confirmed = month.confirmedUserIds.includes(user.id);
  const mark = (value: boolean) => { setUnsaved(value); dirty(value); };
  if (!user.roles.includes('examiner')) return <Panel title="내 심사 업무"><Empty title="심사관 역할이 배정되지 않았습니다.">왼쪽의 AI 담당 업무에서 배정받은 검색 결과를 입력하세요.</Empty></Panel>;
  if (!month.participants.some((entry) => entry.userId === user.id)) return <Panel title="월별 참여 정보"><Empty title="이 운영월의 참여자로 배정되지 않았습니다.">관리자에게 운영월과 그룹 배정을 요청하세요.</Empty></Panel>;
  if (!confirmed) return <SelectionEditor {...props} />;
  const complete = cases.filter((item) => caseStatus(state, item).complete).length;
  return <><div className="ev-stats"><Stat label="내 평가 대상" value={cases.length} note="선정 확정한 출원" /><Stat label="AI 결과 입력 완료" value={cases.filter((item) => caseStatus(state, item).inputComplete).length} note="비교 대상 AI 모두 입력" /><Stat label="평가 완료" value={complete} note={cases.length ? `완료율 ${percent(complete / cases.length)}` : '평가 대상이 없습니다.'} accent /><Stat label="재확인 필요" value={cases.filter((item) => caseStatus(state, item).stale).length} note="평가 후 AI 결과가 바뀐 출원" /></div>
    <div className="ev-actions end" style={{ marginTop: -7, marginBottom: 15 }}><button className="ev-button" onClick={async () => { const result = await exportPersonal(state, month.id, cases); if (result) notify(`업무 자료를 저장했습니다. ${result}`); }}>↓ 내 업무 자료 엑셀</button></div>
    <div className="ev-case-layout"><section className="ev-panel ev-case-list"><div className="ev-case-list-head">내 평가 대상 건 <span className="ev-count">{cases.length}</span></div><div className="ev-case-list-items">{cases.map((item) => <button key={item.id} className={`ev-case ${selected?.id === item.id ? 'active' : ''}`} onClick={() => { if (!unsaved || window.confirm('저장하지 않은 평가가 있습니다. 다른 출원으로 이동하시겠습니까?')) { mark(false); setSelectedId(item.id); } }}><strong>{numberLabel(item.applicationNumber)}</strong><span className="ev-muted">{item.cpc || 'CPC 미입력'}</span><div className="ev-case-status"><Status state={state} item={item} /></div></button>)}</div></section><div>{selected ? <EvaluationEditor key={selected.id} state={state} month={month} save={async (action, message) => { const ok = await save(action, message); if (ok) mark(false); return ok; }} busy={busy} dirty={mark} item={selected} /> : <Panel title="AI 검색 결과 평가"><Empty title="선정 확정한 출원이 없습니다." /></Panel>}</div></div>
  </>;
}

function SelectionEditor({ state, month, user, save, busy, dirty }: Shared & { user: EvaluationUser }) {
  const [rows, setRows] = useState<SelectionRow[]>(() => state.cases.filter((item) => item.monthId === month.id && item.examinerId === user.id && item.status === 'draft').map(({ applicationNumber, cpc }) => ({ applicationNumber, cpc })));
  const [number, setNumber] = useState(''); const [cpc, setCpc] = useState(''); const [paste, setPaste] = useState(''); const [localError, setLocalError] = useState('');
  function add(values: SelectionRow[]) { setRows((previous) => [...previous, ...values]); dirty(true); setLocalError(''); }
  function bulk() { const values = paste.split(/\r?\n/).filter((line) => line.trim()).map((line) => { const match = line.trim().match(/^((?:10|20)[-\s]?\d{4}[-\s]?\d{7})[\s,;\t]*(.*)$/); return match ? { applicationNumber: match[1], cpc: match[2].trim() } : { applicationNumber: line.trim(), cpc: '' }; }); add(values); setPaste(''); }
  const duplicates = rows.filter((row) => state.cases.some((item) => item.monthId === month.id && item.examinerId !== user.id && item.status === 'confirmed' && normalized(item.applicationNumber) === normalized(row.applicationNumber)));
  const disabled = month.closed || busy;
  return <div className="ev-grid2"><Panel title="대상 건 선정" description="이번 달 평가할 출원을 등록하고 목록 전체를 확정하세요." action={<Badge>1단계</Badge>}><div className="ev-panel-body">{localError && <div className="ev-alert">{localError}</div>}<div className="ev-notice">임시저장한 목록은 AI 담당자에게 공개되지 않습니다. 선정 확정 후에는 관리자만 등록·취소할 수 있습니다.{month.selectionDeadline && <><br />선정 기한: {month.selectionDeadline}</>}</div><div className="ev-selection-input"><label>출원번호<input placeholder="10-2024-0000000" value={number} onChange={(event) => { setNumber(event.target.value); dirty(true); }} disabled={disabled} /></label><label>CPC <span className="ev-muted">선택</span><input placeholder="G06N 20/00" value={cpc} onChange={(event) => { setCpc(event.target.value); dirty(true); }} disabled={disabled} /></label><button className="ev-button" disabled={disabled || !number.trim()} onClick={() => { add([{ applicationNumber: number.trim(), cpc: cpc.trim() }]); setNumber(''); setCpc(''); }}>+ 추가</button></div><details style={{ marginTop: 20 }}><summary style={{ cursor: 'pointer', fontSize: 12, color: '#517080' }}>여러 출원 한 번에 붙여넣기</summary><label style={{ marginTop: 12 }}>한 줄에 출원번호와 CPC를 입력하세요.<textarea rows={5} placeholder={'10-2024-0000001\tG06N 20/00\n10-2024-0000002'} value={paste} onChange={(event) => { setPaste(event.target.value); dirty(true); }} disabled={disabled} /></label><div className="ev-actions end"><button className="ev-button" onClick={bulk} disabled={!paste.trim() || disabled}>목록에 추가</button></div></details><hr className="ev-divider" /><div className="ev-subheading"><h3>선정 목록 <span className="ev-count">{rows.length}</span></h3><span className="ev-muted">상한 {month.caseLimit || '제한 없음'}{month.caseLimit ? '건' : ''}</span></div>{duplicates.length > 0 && <div className="ev-notice warning">다른 심사관이 같은 달에 선정한 출원 {duplicates.length}건이 있습니다. 별도의 평가 업무로 유지됩니다.</div>}{rows.length ? <div className="ev-table-scroll"><table className="ev-table"><thead><tr><th>출원번호</th><th>CPC</th><th /></tr></thead><tbody>{rows.map((row, index) => <tr key={index}><td><input aria-label={`출원번호 ${index + 1}`} value={row.applicationNumber} disabled={disabled} onChange={(event) => { setRows(rows.map((value, i) => i === index ? { ...value, applicationNumber: event.target.value } : value)); dirty(true); }} /></td><td><input aria-label={`CPC ${index + 1}`} value={row.cpc} disabled={disabled} onChange={(event) => { setRows(rows.map((value, i) => i === index ? { ...value, cpc: event.target.value } : value)); dirty(true); }} /></td><td><button className="ev-button tiny danger" disabled={disabled} onClick={() => { setRows(rows.filter((_, i) => i !== index)); dirty(true); }}>삭제</button></td></tr>)}</tbody></table></div> : <p className="ev-muted">등록된 출원이 없습니다.</p>}<div className="ev-actions end"><button className="ev-button" disabled={disabled} onClick={() => { if (number.trim() || paste.trim()) { setLocalError('입력 중인 출원을 목록에 먼저 추가해 주세요.'); return; } void save({ type: 'saveSelection', monthId: month.id, rows, confirm: false }, '선정 목록을 임시저장했습니다.'); }}>임시저장</button><button className="ev-button primary" disabled={disabled || !rows.length} onClick={() => { if (number.trim() || paste.trim()) { setLocalError('입력 중인 출원을 목록에 먼저 추가해 주세요.'); return; } if (window.confirm(`${rows.length}건의 선정 목록 전체를 확정하시겠습니까? 확정 후 일반사용자는 목록을 수정할 수 없습니다.`)) void save({ type: 'saveSelection', monthId: month.id, rows, confirm: true }, '대상 건을 확정했습니다. AI 결과가 공개되면 평가할 수 있습니다.'); }}>선정 확정 →</button></div></div></Panel><div><Panel title="선정 후의 업무"><div className="ev-panel-body">{[['01', '전문 PDF 준비', 'AI 담당자가 출원의 전문을 바로 내려받아 검색 자료를 준비합니다.'], ['02', 'AI 검색 결과 입력', '외부 AI 도구에서 확보한 문헌번호를 조사 방식별로 등록합니다.'], ['03', '내 평가 대상 건에서 평가', '공개된 문헌을 평가하고 조사 방식별 순위를 직접 정합니다.']].map(([step, name, text]) => <div className="ev-step" key={step}><span className="ev-step-number">{step}</span><div><h3>{name}</h3><p>{text}</p></div></div>)}</div></Panel></div></div>;
}

function EvaluationEditor({ state, month, item, save, busy, dirty }: Shared & { item: EvaluationCase }) {
  const methods = caseMethods(state, item);
  const ai = methods.filter((method) => method.kind === 'ai');
  const [documents, setDocuments] = useState<Record<string, DocumentEvaluation[]>>(() => Object.fromEntries(ai.map((method) => { const current = validEvaluation(state, item.id, method.id); return [method.id, (resultFor(state, item.id, method.id)?.publishedDocuments || []).map((number) => current?.documents.find((document) => normalized(document.number) === normalized(number)) || { number, score: null, cited: null, note: '' })]; })));
  const [ranks, setRanks] = useState<Record<string, RankValue>>(() => { const ranking = state.rankings.find((value) => value.caseId === item.id); return rankingIsCurrent(state, item, ranking) ? ranking?.values || {} : {}; });
  const versions = Object.fromEntries(ai.map((method) => [method.id, resultFor(state, item.id, method.id)?.publishedVersion || 0]));
  function update(methodId: string, index: number, patch: Partial<DocumentEvaluation>) { setDocuments((previous) => ({ ...previous, [methodId]: previous[methodId].map((document, i) => i === index ? { ...document, ...patch } : document) })); dirty(true); }
  const status = caseStatus(state, item); const disabled = month.closed || busy;
  return <><div className="ev-case-title"><div><h2>{numberLabel(item.applicationNumber)}</h2><p className="ev-muted">{item.cpc || 'CPC 미입력'} · {item.examinerName} · {item.groupName}</p></div><div className="ev-actions"><Status state={state} item={item} /></div></div><CaseResource item={item} demo={state.isDemo} />{status.stale && <div className="ev-notice warning">평가 후 AI 검색 결과가 변경되었습니다. 바뀐 방식의 문헌 평가와 품질 순위를 다시 확인해 저장하세요.</div>}<Panel title="AI 문헌별 평가" description="미선택은 실제 0점·X와 다릅니다. 일부 항목만 입력한 상태도 저장할 수 있습니다."><div className="ev-table-scroll" style={{ minHeight: 240 }}><table className="ev-table"><thead><tr><th>조사 방식</th><th>문헌</th><th>점수</th><th>인용여부</th><th>비고</th></tr></thead><tbody>{ai.flatMap((method) => (documents[method.id] || []).map((document, index) => <tr key={`${method.id}:${document.number}`}><td>{method.name}</td><td className="ev-doc"><a href={`https://patents.google.com/?q=${encodeURIComponent(document.number)}`} target="_blank" rel="noreferrer" title="새 창에서 문헌 검색">{document.number} ↗</a></td><td><select aria-label={`${method.name} ${document.number} 점수`} value={document.score ?? ''} disabled={disabled} onChange={(event) => update(method.id, index, { score: event.target.value === '' ? null : Number(event.target.value) })}><option value="">미선택</option>{[0, 1, 2, 3, 4, 5].map((value) => <option key={value} value={value}>{value}점</option>)}</select></td><td><select aria-label={`${method.name} ${document.number} 인용여부`} value={document.cited ?? ''} disabled={disabled} onChange={(event) => update(method.id, index, { cited: event.target.value === '' ? null : event.target.value as 'O' | 'X' })}><option value="">미선택</option><option value="O">O</option><option value="X">X</option></select></td><td><input style={{ minWidth: 150 }} aria-label={`${method.name} ${document.number} 비고`} placeholder="선택 입력" value={document.note} maxLength={4000} disabled={disabled} onChange={(event) => update(method.id, index, { note: event.target.value })} /></td></tr>))}{!Object.values(documents).some((values) => values.length) && <tr><td colSpan={5}><Empty title="공개된 AI 검색 결과를 기다리고 있습니다.">AI 담당자가 입력 완료하면 여기에 문헌이 표시됩니다.</Empty></td></tr>}</tbody></table></div><div className="ev-kpi-note">{ai.map((method) => <span key={method.id}>{method.name} {versions[method.id] ? `${documents[method.id]?.length || 0}문헌` : '대기 중'}</span>)}</div></Panel><Panel title="조사 방식별 품질 순위" description="선행기술조사와 AI 결과 전체를 비교해 직접 순위를 매깁니다. 동순위 없이 1위부터 연속해서 선택하세요."><div className="ev-table-scroll"><table className="ev-table"><thead><tr><th>조사 방식</th><th>입력 상태</th><th>품질 순위</th></tr></thead><tbody>{methods.map((method) => { const available = method.kind === 'baseline' || versions[method.id] > 0; return <tr key={method.id}><td>{method.name}</td><td>{method.kind === 'baseline' ? <Badge>순위 비교 전용</Badge> : <Badge color={available ? 'green' : ''}>{available ? '입력 완료' : '대기 중'}</Badge>}</td><td><select aria-label={`${method.name} 품질 순위`} value={ranks[method.id] ?? ''} disabled={disabled || !available} onChange={(event) => { const value = event.target.value; setRanks((previous) => ({ ...previous, [method.id]: value === '' ? null : /^[123]$/.test(value) ? Number(value) as 1 | 2 | 3 : value as RankValue })); dirty(true); }}><option value="">{available ? '미선택' : '대기 중'}</option><option value="1">1위</option><option value="2">2위</option><option value="3">3위</option><option value="unranked">순위 외</option><option value="excluded">평가 제외</option><option value="incomparable">비교 불가</option></select></td></tr>; })}</tbody></table></div></Panel><div className="ev-actions end"><span className="ev-muted">{month.evaluationDeadline ? `평가 기한 ${month.evaluationDeadline}` : '평가 기한 제한 없음'}</span><button className="ev-button primary" disabled={disabled} onClick={() => void save({ type: 'saveEvaluation', caseId: item.id, evaluations: ai.filter((method) => versions[method.id] > 0).map((method) => ({ methodId: method.id, version: versions[method.id], documents: documents[method.id] || [] })), rankings: ranks, versions }, '문헌 평가와 품질 순위를 저장했습니다.')}>{busy ? '저장 중…' : '평가 저장'}</button></div></>;
}

function AIWorkspace({ state, month, user, save, busy, dirty, notify }: Shared & { user: EvaluationUser; notify: (text: string) => void }) {
  const assignments = month.assignments.filter((assignment) => assignment.userId === user.id);
  const tasks = state.cases.filter((item) => item.monthId === month.id && item.status === 'confirmed').flatMap((item) => assignments.filter((assignment) => assignment.groupId === item.groupId).map((assignment) => ({ item, methodId: assignment.methodId, key: `${item.id}:${assignment.methodId}` })));
  const [selectedKey, setSelectedKey] = useState(''); const [unsaved, setUnsaved] = useState(false); const [filter, setFilter] = useState('');
  const visible = filter ? tasks.filter((task) => !resultFor(state, task.item.id, task.methodId)?.publishedVersion) : tasks;
  const selected = visible.find((task) => task.key === selectedKey) || visible[0];
  const complete = tasks.filter((task) => resultFor(state, task.item.id, task.methodId)?.publishedVersion).length;
  function mark(value: boolean) { setUnsaved(value); dirty(value); }
  return <><div className="ev-stats"><Stat label="배정받은 입력 업무" value={tasks.length} note="출원 × AI 조사 방식 기준" /><Stat label="입력 완료" value={complete} note="심사관에게 공개한 검색 결과" accent /><Stat label="입력 대기" value={tasks.length - complete} note="초안만 저장한 결과 포함" /><Stat label="담당 조사 방식" value={new Set(assignments.map((assignment) => assignment.methodId)).size} unit="개" note={assignments.map((assignment) => state.methods.find((method) => method.id === assignment.methodId)?.name).filter((value, i, values) => values.indexOf(value) === i).join(' · ')} /></div><div className="ev-filter"><select aria-label="AI 업무 진행 상태" value={filter} onChange={(event) => { if (!unsaved || window.confirm('저장하지 않은 검색 결과가 있습니다. 필터를 바꾸시겠습니까?')) { mark(false); setFilter(event.target.value); } }}><option value="">전체 입력 업무</option><option value="pending">입력 대기만 보기</option></select><span className="ev-muted">선정 확정된 담당 그룹 출원만 표시됩니다.</span><button className="ev-button" style={{ marginLeft: 'auto' }} onClick={async () => { const items = [...new Map(tasks.map((task) => [task.item.id, task.item])).values()]; const result = await exportPersonal(state, month.id, items); if (result) notify(`담당 업무 자료를 저장했습니다. ${result}`); }}>↓ 담당 업무 자료 엑셀</button></div><div className="ev-case-layout"><section className="ev-panel ev-case-list"><div className="ev-case-list-head">담당 입력 업무 <span className="ev-count">{visible.length}</span></div><div className="ev-case-list-items">{visible.map((task) => <button key={task.key} className={`ev-case ${selected?.key === task.key ? 'active' : ''}`} onClick={() => { if (!unsaved || window.confirm('저장하지 않은 검색 결과가 있습니다. 다른 업무로 이동하시겠습니까?')) { mark(false); setSelectedKey(task.key); } }}><strong>{numberLabel(task.item.applicationNumber)}</strong><span className="ev-muted">{task.item.examinerName} · {task.item.groupName}</span><div className="ev-case-status"><Badge>{state.methods.find((method) => method.id === task.methodId)?.name}</Badge><Badge color={resultFor(state, task.item.id, task.methodId)?.publishedVersion ? 'green' : ''}>{resultFor(state, task.item.id, task.methodId)?.publishedVersion ? '입력 완료' : '대기 중'}</Badge></div></button>)}</div>{!visible.length && <Empty title="표시할 업무가 없습니다." />}</section><div>{selected ? <AIResultEditor key={selected.key} state={state} month={month} item={selected.item} methodId={selected.methodId} save={async (action, message) => { const ok = await save(action, message); if (ok) mark(false); return ok; }} busy={busy} dirty={mark} /> : <Panel title="AI 검색 결과 입력"><Empty title="이 운영월에 배정받은 업무가 없습니다.">담당 그룹·조사 방식의 배정과 대상 건 확정 여부를 확인하세요.</Empty></Panel>}</div></div></>;
}

function AIResultEditor({ state, month, item, methodId, save, busy, dirty }: Shared & { item: EvaluationCase; methodId: string }) {
  const result = resultFor(state, item.id, methodId); const method = state.methods.find((candidate) => candidate.id === methodId);
  const [input, setInput] = useState((result?.draftDocuments || []).join('\n'));
  const documents = input.split(/\r?\n/).map((number) => number.trim()).filter(Boolean);
  const disabled = month.closed || busy;
  return <><div className="ev-case-title"><div><h2>{numberLabel(item.applicationNumber)}</h2><p className="ev-muted">{item.examinerName} · {item.groupName} · {item.cpc || 'CPC 미입력'}</p></div><Badge>{method?.name}</Badge></div><CaseResource item={item} demo={state.isDemo} /><Panel title="AI 검색 결과 입력" description={`${method?.name}에서 확보한 선행기술 문헌번호를 한 줄에 하나씩 입력하세요.`} action={<Badge color={documents.length > 7 ? 'red' : ''}>{documents.length} / 7문헌</Badge>}><div className="ev-panel-body"><div className="ev-notice">외부 AI 도구에서 검색을 수행한 뒤 문헌번호만 등록합니다. 제목·유형·파일 첨부는 필요하지 않습니다.</div><label>선행기술 문헌번호<textarea rows={9} spellCheck={false} style={{ fontFamily: 'Consolas, monospace', fontSize: 14 }} value={input} placeholder={'KR1020230000001A\nUS20230000001A1\nEP4000000A1'} disabled={disabled} onChange={(event) => { setInput(event.target.value); dirty(true); }} /></label>{documents.length > 7 && <p style={{ color: '#ae4f42', marginTop: 9, fontSize: 12 }}>출원 1건 × AI 방식 1개당 최대 7문헌입니다.</p>}<div className="ev-actions end"><span className="ev-muted" style={{ marginRight: 'auto' }}>{month.resultDeadline ? `입력 기한 ${month.resultDeadline}` : '입력 기한 제한 없음'}</span><button className="ev-button" disabled={disabled || documents.length > 7} onClick={() => void save({ type: 'saveResult', caseId: item.id, methodId, documents, publish: false }, '검색 결과 초안을 임시저장했습니다. 심사관에게는 아직 공개되지 않습니다.')}>임시저장</button><button className="ev-button primary" disabled={disabled || !documents.length || documents.length > 7} onClick={() => void save({ type: 'saveResult', caseId: item.id, methodId, documents, publish: true }, 'AI 검색 결과 입력을 완료했습니다. 담당 심사관에게 공개되었습니다.')}>AI 검색 결과 입력 완료</button></div></div></Panel><Panel title="심사관에게 공개된 결과" description={result?.publishedBy ? `실제 등록자 ${result.publishedBy.name} · ${result.publishedAt ? new Date(result.publishedAt).toLocaleString('ko-KR', { timeZone: 'Asia/Seoul' }) : ''}` : '입력 완료한 결과만 심사관에게 공개됩니다.'}>{result?.publishedDocuments.length ? <><div className="ev-table-scroll"><table className="ev-table"><thead><tr><th>순서</th><th>문헌번호</th><th>원문 확인</th></tr></thead><tbody>{result.publishedDocuments.map((number, index) => <tr key={number}><td>{index + 1}</td><td className="ev-doc">{number}</td><td><a className="ev-button tiny" href={`https://patents.google.com/?q=${encodeURIComponent(number)}`} target="_blank" rel="noreferrer">문헌 검색 ↗</a></td></tr>)}</tbody></table></div><div className="ev-kpi-note">수정 초안은 다시 입력 완료하기 전까지 기존 공개 결과를 바꾸지 않습니다.<a className="ev-button tiny" href={`/documents?numbers=${encodeURIComponent(result.publishedDocuments.join('\n'))}`}>검색 문헌 PDF 모으기 ↗</a></div></> : <Empty title="아직 공개한 결과가 없습니다.">한 문헌 이상 입력한 뒤 ‘AI 검색 결과 입력 완료’를 누르세요.</Empty>}</Panel></>;
}

async function exportPersonal(state: EvaluationState, monthId: string, cases: EvaluationCase[]) {
  const ids = new Set(cases.map((item) => item.id)); const stats = getStatistics(state, monthId); const rows = stats.rows.filter((row) => ids.has(row.caseId));
  return exportWorkbook(`심사데스크_업무자료_${monthId}.xlsx`, [
    { name: '출원별 현황', rows: [['출원번호', 'CPC', '담당 심사관', '그룹', 'AI 입력 상태', '평가 상태'], ...cases.map((item) => [item.applicationNumber, item.cpc, item.examinerName, item.groupName, caseStatus(state, item).inputComplete ? '입력 완료' : '대기 중', caseStatus(state, item).evaluationStatus])] },
    { name: '선행기술 목록', rows: [['출원번호', '조사 방식', '문헌번호', 'AI 담당자'], ...rows.map((row) => [row.applicationNumber, row.methodName, row.number, row.authorName])] },
    { name: '품질 순위', rows: [['출원번호', '조사 방식', '순위', '유효 여부'], ...cases.flatMap((item) => { const rank = state.rankings.find((entry) => entry.caseId === item.id); return caseMethods(state, item).map((method) => [item.applicationNumber, method.name, rank?.values[method.id] == null ? '—' : rankLabel(rank.values[method.id]), rankingIsCurrent(state, item, rank) ? '현재 결과' : rank ? '재확인 필요' : '미평가']); })] },
    { name: '문헌별 평가', rows: [['출원번호', '조사 방식', '문헌번호', '점수', '인용여부', '비고', '평가 상태'], ...rows.map((row) => [row.applicationNumber, row.methodName, row.number, row.score, row.cited, row.note, row.status])] },
  ]);
}
function rankLabel(value: RankValue) { return typeof value === 'number' ? `${value}위` : value === 'unranked' ? '순위 외' : value === 'excluded' ? '평가 제외' : value === 'incomparable' ? '비교 불가' : '—'; }

function AdminStats({ state, month, save, busy, notify }: Shared & { notify: (text: string) => void }) {
  const [groupId, setGroupId] = useState(''); const [examinerId, setExaminerId] = useState(''); const [tab, setTab] = useState('cases');
  const stats = useMemo(() => getStatistics(state, month.id, groupId, examinerId), [state, month.id, groupId, examinerId]);
  const { summary } = stats;
  const filters = { monthId: month.id, group: state.groups.find((group) => group.id === groupId)?.name || '전체 그룹', examiner: state.users.find((user) => user.id === examinerId)?.name || '전체 심사관' };
  async function exportStats() { const result = await exportWorkbook(`심사데스크_관리자통계_${month.id}.xlsx`, [
    { name: '그룹별 통계', rows: [['그룹', '참여자', '확정 출원', 'AI 입력 완료', '평가 완료', '문헌 수', '평가 완료율'], ...stats.groups.map((row) => [row.name, row.participants, row.cases, row.inputComplete, row.complete, row.documents, percent(row.completionRate)])] },
    { name: '계정별 현황', rows: [['심사과', '이름', '개인 출원', '평가 완료', 'AI 담당 대상', 'AI 담당 입력 완료'], ...stats.accounts.map((row) => [row.division, row.name, row.cases, row.complete, row.aiTarget, row.aiCompleted])] },
    { name: '출원별 현황', rows: [['출원번호', 'CPC', '담당 심사관', '그룹', 'AI 입력 상태', '평가 상태'], ...stats.cases.map((row) => [row.applicationNumber, row.cpc, row.examinerName, row.groupName, row.inputComplete ? '입력 완료' : '대기 중', row.evaluationStatus])] },
    { name: '조사 방식별 통계', rows: [['조사 방식', '입력 대상', '입력 완료', '입력 대기', '문헌 수', '평균 점수', '인용률', '1위 횟수'], ...stats.methods.map((row) => [row.name, row.target, row.completed, row.pending, row.documents, row.averageScore, percent(row.citationRate), row.firstPlace])] },
    { name: 'AI 검색 결과 평가', rows: [['출원번호', '담당 심사관', 'AI 담당자', '조사 방식', 'AI 검색 결과', '인용여부', '점수', '평가 상태'], ...stats.rows.map((row) => [row.applicationNumber, row.examinerName, row.authorName, row.methodName, row.number, row.cited, row.score, row.status])] },
    { name: '조회 기준', rows: [['항목', '값'], ['운영월', filters.monthId], ['그룹', filters.group], ['담당 심사관', filters.examiner], ['집계 기준', '선정 확정·공개된 최신 AI 결과의 유효 평가. 초안·취소 출원 제외.'], ['가상 자료 여부', state.isDemo ? '가상 검증 자료' : '운영 자료']] },
  ]); if (result) notify(`현재 조회 기준으로 통계 파일을 저장했습니다. ${result}`); }
  return <><div className="ev-filter"><select aria-label="그룹 필터" value={groupId} onChange={(event) => { setGroupId(event.target.value); setExaminerId(''); }}><option value="">전체 그룹</option>{state.groups.map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</select><select aria-label="담당 심사관 필터" value={examinerId} onChange={(event) => setExaminerId(event.target.value)}><option value="">전체 심사관</option>{state.users.filter((user) => month.participants.some((entry) => entry.userId === user.id && (!groupId || entry.groupId === groupId))).map((user) => <option key={user.id} value={user.id}>{user.division} - {user.name}</option>)}</select><span className="ev-muted">계정은 담당 심사관 기준</span><button className="ev-button" style={{ marginLeft: 'auto' }} onClick={() => void exportStats()}>↓ 현재 범위 엑셀 저장</button><button className={`ev-button ${month.closed ? 'primary' : ''}`} disabled={busy} onClick={() => { if (window.confirm(month.closed ? '이 운영월을 다시 여시겠습니까?' : '이 운영월의 입력과 평가를 마감하시겠습니까?')) void save({ type: 'setMonthClosed', monthId: month.id, closed: !month.closed }, month.closed ? '운영월을 재개방했습니다.' : '운영월을 마감했습니다.'); }}>{month.closed ? '운영 재개방' : '월 운영 마감'}</button></div><div className="ev-stats"><Stat label="참여 심사관" value={summary.participants} unit="명" note={`미선정 ${summary.unselected}명`} /><Stat label="확정 출원" value={summary.cases} note={`AI 입력 대기 ${summary.inputPending}건`} /><Stat label="AI 입력 완료" value={summary.inputComplete} note={`입력 완료율 ${percent(summary.inputRate)}`} /><Stat label="평가 완료" value={summary.complete} note={`평가 완료율 ${percent(summary.evaluationRate)}`} accent /></div><div className="ev-grid2"><Panel title="그룹별 진행" description="선정 확정한 출원 기준"><div className="ev-table-scroll"><table className="ev-table"><thead><tr><th>그룹</th><th>출원</th><th>입력 완료</th><th>평가 완료</th><th>완료율</th></tr></thead><tbody>{stats.groups.map((row) => <tr key={row.id}><td>{row.name}</td><td>{row.cases}</td><td>{row.inputComplete}</td><td>{row.complete}</td><td style={{ minWidth: 110 }}>{percent(row.completionRate)}<div className="ev-progress"><span style={{ width: `${(row.completionRate || 0) * 100}%` }} /></div></td></tr>)}{!stats.groups.length && <tr><td colSpan={5}><Empty title="등록된 그룹이 없습니다." /></td></tr>}</tbody></table></div></Panel><Panel title="조사 방식별 비교" description="미선택은 평균·인용률 집계에서 제외합니다."><div className="ev-table-scroll"><table className="ev-table"><thead><tr><th>조사 방식</th><th>문헌 수</th><th>평균 점수</th><th>인용률</th><th>1위 횟수</th></tr></thead><tbody>{stats.methods.map((row) => <tr key={row.id}><td>{row.name}</td><td>{row.kind === 'baseline' ? '—' : row.documents}</td><td>{row.averageScore === null ? '—' : `${row.averageScore.toFixed(2)}점`}</td><td>{percent(row.citationRate)}</td><td>{row.firstPlace}</td></tr>)}</tbody></table></div></Panel></div><section className="ev-panel" style={{ marginTop: 22 }}><div className="ev-panel-head"><div><h2>업무 상세 현황</h2><p>미평가 {summary.unevaluated} · 평가 중 {summary.inProgress} · 재확인 필요 {summary.recheck}</p></div><Badge>{summary.documents}문헌</Badge></div><div className="ev-tabs">{[['cases', '출원별 현황'], ['accounts', '계정별 현황'], ['documents', 'AI 검색 결과 평가']].map(([id, label]) => <button key={id} className={`ev-tab ${tab === id ? 'active' : ''}`} onClick={() => setTab(id)}>{label}</button>)}</div><div className="ev-table-scroll"><table className="ev-table">{tab === 'cases' ? <><thead><tr><th>출원번호</th><th>CPC</th><th>담당 심사관</th><th>그룹</th><th>AI 입력</th><th>평가 상태</th><th /></tr></thead><tbody>{stats.cases.map((row) => <tr key={row.id}><td className="ev-doc">{row.applicationNumber}</td><td>{row.cpc || '—'}</td><td>{row.examinerName}</td><td>{row.groupName}</td><td><Badge color={row.inputComplete ? 'green' : ''}>{row.inputComplete ? '입력 완료' : '대기 중'}</Badge></td><td><Badge color={row.complete ? 'green' : row.stale ? 'orange' : ''}>{row.evaluationStatus}</Badge></td><td><button className="ev-button tiny danger" disabled={busy || month.closed} onClick={() => { if (window.confirm(`${row.applicationNumber} 출원을 취소하시겠습니까? 집계에서 제외됩니다.`)) void save({ type: 'cancelCase', caseId: row.id }, '출원을 취소했습니다.'); }}>취소</button></td></tr>)}</tbody></> : tab === 'accounts' ? <><thead><tr><th>심사과</th><th>이름</th><th>개인 출원</th><th>평가 완료</th><th>AI 담당 대상</th><th>AI 입력 완료</th></tr></thead><tbody>{stats.accounts.map((row) => <tr key={row.id}><td>{row.division}</td><td>{row.name}</td><td>{row.cases}</td><td>{row.complete}</td><td>{row.aiTarget}</td><td>{row.aiCompleted}</td></tr>)}</tbody></> : <><thead><tr><th>출원번호</th><th>담당 심사관</th><th>AI 담당자</th><th>조사 방식</th><th>AI 검색 결과</th><th>인용여부</th><th>점수</th><th>평가 상태</th></tr></thead><tbody>{stats.rows.map((row) => <tr key={`${row.caseId}:${row.methodId}:${row.number}`}><td className="ev-doc">{row.applicationNumber}</td><td>{row.examinerName}</td><td>{row.authorName}</td><td>{row.methodName}</td><td className="ev-doc">{row.number}</td><td>{row.cited ?? '—'}</td><td>{row.score ?? '—'}</td><td><Badge color={row.status === '평가 완료' ? 'green' : row.status === '재확인 필요' ? 'orange' : ''}>{row.status}</Badge></td></tr>)}</tbody></>}</table>{!stats.cases.length && <Empty title="현재 조회 범위에 확정 출원이 없습니다.">선정 초안과 취소 출원은 통계에 포함하지 않습니다.</Empty>}</div></section></>;
}

function AdminSettings({ state, month, save, busy, dirty, hasUnsaved, selectMonth }: Shared & { selectMonth: (id: string) => void }) {
  const [tab, setTab] = useState('month');
  const [newMonth, setNewMonth] = useState('');
  const switchTab = (value: string) => { if (!hasUnsaved || window.confirm('저장하지 않은 설정이 있습니다. 다른 설정으로 이동하시겠습니까?')) { dirty(false); setTab(value); } };
  return <><div className="ev-tabs" style={{ paddingLeft: 0, marginBottom: 22 }}>{[['month', '월별 운영·배정'], ['users', '사용자 관리'], ['groups', '그룹·조사 방식'], ['cases', '출원 운영']].map(([id, label]) => <button key={id} className={`ev-tab ${tab === id ? 'active' : ''}`} onClick={() => tab !== id && switchTab(id)}>{label}</button>)}</div>{tab === 'month' ? <><div className="ev-filter"><label style={{ display: 'flex', alignItems: 'center' }}>새 운영월<input type="month" value={newMonth} onChange={(event) => setNewMonth(event.target.value)} /></label><button className="ev-button" disabled={!newMonth || busy || state.months.some((entry) => entry.id === newMonth)} onClick={async () => { if (await save({ type: 'saveMonth', month: emptyMonth(newMonth) }, '새 운영월을 추가했습니다.')) { selectMonth(newMonth); setNewMonth(''); } }}>+ 운영월 추가</button></div><MonthSettings key={`${month.id}:${state.users.length}:${state.groups.length}:${state.methods.length}`} state={state} month={month} save={save} busy={busy} dirty={dirty} /></> : tab === 'users' ? <UserSettings state={state} month={month} save={save} busy={busy} dirty={dirty} hasUnsaved={hasUnsaved} /> : tab === 'groups' ? <GroupSettings state={state} month={month} save={save} busy={busy} dirty={dirty} hasUnsaved={hasUnsaved} /> : <CaseSettings state={state} month={month} save={save} busy={busy} dirty={dirty} />}{!state.users.length && !state.groups.length && !state.cases.length && <div className="ev-notice" style={{ marginTop: 24 }}><strong>검증용 시나리오 체험</strong><p style={{ marginTop: 5 }}>운영 자료가 없는 초기 상태에서만 10명·2그룹·20출원·280문헌의 가상 자료를 불러올 수 있습니다.</p><button className="ev-button" style={{ marginTop: 10 }} disabled={busy} onClick={() => { if (window.confirm('가상 검증 자료를 불러오시겠습니까? 실제 출원이나 실적이 아닌 검증용 예시가 저장됩니다.')) void save({ type: 'loadDemo' }, '가상 검증 자료를 불러왔습니다.'); }}>가상 검증 자료 불러오기</button></div>}</>;
}

function MonthSettings({ state, month, save, busy, dirty }: Shared) {
  const [form, setForm] = useState<OperationMonth>(() => structuredClone(month));
  const update = (patch: Partial<OperationMonth>) => { setForm((previous) => ({ ...previous, ...patch })); dirty(true); };
  const ai = state.methods.filter((method) => method.kind === 'ai' && form.methodIds.includes(method.id));
  const disabled = busy;
  return <><Panel title="월별 운영 설정" description="기한을 비워두면 제한 없음, 건수 상한 0은 제한 없음으로 처리합니다."><div className="ev-panel-body"><div className="ev-field-grid"><label>대상 건 선정 기한<input type="date" value={form.selectionDeadline} onChange={(event) => update({ selectionDeadline: event.target.value })} disabled={disabled} /></label><label>AI 결과 입력 기한<input type="date" value={form.resultDeadline} onChange={(event) => update({ resultDeadline: event.target.value })} disabled={disabled} /></label><label>평가 기한<input type="date" value={form.evaluationDeadline} onChange={(event) => update({ evaluationDeadline: event.target.value })} disabled={disabled} /></label><label>심사관별 출원 건수 상한<input type="number" min="0" max="500" value={form.caseLimit} onChange={(event) => update({ caseLimit: Number(event.target.value) })} disabled={disabled} /></label></div><div className="ev-subheading"><h3>비교 조사 방식</h3></div><div className="ev-checks">{state.methods.map((method) => <label key={method.id}><input type="checkbox" checked={form.methodIds.includes(method.id)} disabled={disabled} onChange={(event) => { const ids = event.target.checked ? [...form.methodIds, method.id] : form.methodIds.filter((id) => id !== method.id); update({ methodIds: ids, assignments: form.assignments.filter((assignment) => ids.includes(assignment.methodId)) }); }} />{method.name}{method.kind === 'baseline' && <Badge>순위 전용</Badge>}</label>)}</div></div></Panel><Panel title="참여 심사관 · 그룹 배정" description="한 운영월에 심사관 한 명은 하나의 그룹에 참여합니다."><div className="ev-table-scroll"><table className="ev-table"><thead><tr><th>심사과</th><th>이름</th><th>참여 그룹</th></tr></thead><tbody>{state.users.filter((user) => user.roles.includes('examiner')).map((user) => <tr key={user.id}><td>{user.division}</td><td>{user.name} {!user.active && <Badge>비활성</Badge>}</td><td><select aria-label={`${user.name} 참여 그룹`} disabled={disabled} value={form.participants.find((entry) => entry.userId === user.id)?.groupId || ''} onChange={(event) => update({ participants: [...form.participants.filter((entry) => entry.userId !== user.id), ...(event.target.value ? [{ userId: user.id, groupId: event.target.value }] : [])] })}><option value="">참여하지 않음</option>{state.groups.map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</select></td></tr>)}</tbody></table>{!state.users.length && <Empty title="사용자를 먼저 등록하세요." />}</div></Panel><Panel title="그룹별 AI 담당자 배정" description="운영월 × 그룹 × AI 방식마다 한 명을 배정합니다. 한 사람이 여러 업무를 맡을 수 있습니다."><div className="ev-table-scroll"><table className="ev-table"><thead><tr><th>그룹</th>{ai.map((method) => <th key={method.id}>{method.name}</th>)}</tr></thead><tbody>{state.groups.map((group) => <tr key={group.id}><td>{group.name}</td>{ai.map((method) => <td key={method.id}><select aria-label={`${group.name} ${method.name} 담당자`} disabled={disabled} value={form.assignments.find((entry) => entry.groupId === group.id && entry.methodId === method.id)?.userId || ''} onChange={(event) => update({ assignments: [...form.assignments.filter((entry) => !(entry.groupId === group.id && entry.methodId === method.id)), ...(event.target.value ? [{ groupId: group.id, methodId: method.id, userId: event.target.value }] : [])] })}><option value="">배정하지 않음</option>{state.users.filter((user) => user.active && user.roles.includes('ai')).map((user) => <option key={user.id} value={user.id}>{user.division} - {user.name}</option>)}</select></td>)}</tr>)}</tbody></table>{!state.groups.length && <Empty title="그룹을 먼저 등록하세요." />}</div></Panel><div className="ev-actions end"><button className="ev-button primary" disabled={busy} onClick={() => void save({ type: 'saveMonth', month: form }, '월별 운영과 담당 배정을 저장했습니다.')}>월별 운영·배정 저장</button></div></>;
}

function UserSettings({ state, save, busy, dirty, hasUnsaved }: Shared) {
  const blank: Omit<EvaluationUser, 'id'> & { id?: string } = { name: '', bureau: '', division: '', roles: ['examiner'], active: true };
  const [form, setForm] = useState(blank); const [mode, setMode] = useState<'new' | 'edit'>('new');
  function update(patch: Partial<typeof form>) { setForm((previous) => ({ ...previous, ...patch })); dirty(true); }
  return <div className="ev-grid2"><Panel title="기존 사용자 관리" description="사용자를 선택하면 오른쪽에 정보를 불러옵니다." action={<Badge>{state.users.length}명</Badge>}><div className="ev-table-scroll"><table className="ev-table"><thead><tr><th>심사과</th><th>이름</th><th>역할</th><th>상태</th></tr></thead><tbody>{state.users.map((user) => <tr key={user.id} onClick={() => { if (!hasUnsaved || window.confirm('저장하지 않은 사용자 정보가 있습니다. 선택한 사용자를 불러오시겠습니까?')) { setMode('edit'); setForm(structuredClone(user)); dirty(false); } }} style={{ cursor: 'pointer', background: form.id === user.id ? '#edf7f4' : undefined }}><td>{user.division}</td><td><strong>{user.name}</strong></td><td>{user.roles.map((role) => roleLabels[role]).join(' · ')}</td><td><Badge color={user.active ? 'green' : ''}>{user.active ? '활성' : '비활성'}</Badge></td></tr>)}</tbody></table>{!state.users.length && <Empty title="등록된 사용자가 없습니다." />}</div></Panel><Panel title={mode === 'new' ? '신규 사용자 등록' : '사용자 정보 수정'} action={<button className="ev-button tiny" onClick={() => { if (!hasUnsaved || window.confirm('입력 중인 내용을 지우고 신규 사용자 등록을 시작하시겠습니까?')) { setMode('new'); setForm({ ...blank }); dirty(false); } }}>+ 신규 사용자</button>}><div className="ev-panel-body ev-form-stack"><label>이름<input value={form.name} maxLength={200} onChange={(event) => update({ name: event.target.value })} /></label><div className="ev-field-grid"><label>심사국<input value={form.bureau} maxLength={200} onChange={(event) => update({ bureau: event.target.value })} /></label><label>심사과<input value={form.division} maxLength={200} onChange={(event) => update({ division: event.target.value })} /></label></div><div><label>역할</label><div className="ev-checks">{(['examiner', 'ai', 'admin'] as Role[]).map((role) => <label key={role}><input type="checkbox" checked={form.roles.includes(role)} onChange={(event) => update({ roles: event.target.checked ? [...form.roles, role] : form.roles.filter((entry) => entry !== role) })} />{roleLabels[role]}</label>)}</div></div><label style={{ display: 'flex', alignItems: 'center' }}><input type="checkbox" checked={form.active} onChange={(event) => update({ active: event.target.checked })} />활성 사용자</label><p className="ev-muted">비활성화해도 과거 업무와 실제 결과 등록자 기록은 유지됩니다.</p><div className="ev-actions end"><button className="ev-button primary" disabled={busy || !form.name.trim() || !form.roles.length} onClick={async () => { if (await save({ type: 'saveUser', user: form }, mode === 'new' ? '사용자를 등록했습니다.' : '사용자 정보를 저장했습니다.')) { if (mode === 'new') setForm({ ...blank }); } }}>{mode === 'new' ? '사용자 등록' : '사용자 정보 저장'}</button></div></div></Panel></div>;
}

function GroupSettings({ state, save, busy, dirty, hasUnsaved }: Shared) {
  const [groupId, setGroupId] = useState(''); const [groupName, setGroupName] = useState('');
  const [methodId, setMethodId] = useState(''); const [methodName, setMethodName] = useState(''); const [methodKind, setMethodKind] = useState<'ai' | 'baseline'>('ai'); const [active, setActive] = useState(true);
  useEffect(() => { const group = state.groups.find((entry) => entry.id === groupId); const method = state.methods.find((entry) => entry.id === methodId); dirty(groupName !== (group?.name || '') || methodName !== (method?.name || '') || methodKind !== (method?.kind || 'ai') || active !== (method?.active ?? true)); }, [state.groups, state.methods, groupId, groupName, methodId, methodName, methodKind, active, dirty]);
  return <div className="ev-grid2"><Panel title="그룹 관리" description="그룹을 선택해 수정하거나 새 그룹을 등록합니다."><div className="ev-panel-body ev-form-stack"><label>기존 그룹<select value={groupId} onChange={(event) => { if (hasUnsaved && !window.confirm('저장하지 않은 설정이 있습니다. 선택한 그룹을 불러오시겠습니까?')) return; const group = state.groups.find((entry) => entry.id === event.target.value); setGroupId(group?.id || ''); setGroupName(group?.name || ''); dirty(false); }}><option value="">+ 새 그룹</option>{state.groups.map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</select></label><label>그룹 이름<input value={groupName} maxLength={200} onChange={(event) => { setGroupName(event.target.value); dirty(true); }} /></label><div className="ev-actions end"><button className="ev-button primary" disabled={busy || !groupName.trim()} onClick={async () => { if (await save({ type: 'saveGroup', group: { id: groupId || undefined, name: groupName } }, '그룹을 저장했습니다.')) { setGroupId(''); setGroupName(''); } }}>그룹 저장</button></div></div></Panel><Panel title="조사 방식 관리" description="AI 방식은 자유롭게 추가하고 월별 비교 참여를 정합니다."><div className="ev-panel-body ev-form-stack"><label>기존 조사 방식<select value={methodId} onChange={(event) => { if (hasUnsaved && !window.confirm('저장하지 않은 설정이 있습니다. 선택한 조사 방식을 불러오시겠습니까?')) return; const method = state.methods.find((entry) => entry.id === event.target.value); setMethodId(method?.id || ''); setMethodName(method?.name || ''); setMethodKind(method?.kind || 'ai'); setActive(method?.active ?? true); dirty(false); }}><option value="">+ 새 조사 방식</option>{state.methods.map((method) => <option key={method.id} value={method.id}>{method.name}</option>)}</select></label><label>조사 방식 이름<input value={methodName} maxLength={200} onChange={(event) => { setMethodName(event.target.value); dirty(true); }} /></label><label>업무 유형<select value={methodKind} onChange={(event) => { setMethodKind(event.target.value as 'ai' | 'baseline'); dirty(true); }}><option value="ai">AI 조사 방식</option><option value="baseline">순위 비교 전용</option></select></label><label style={{ display: 'flex', alignItems: 'center' }}><input type="checkbox" checked={active} onChange={(event) => { setActive(event.target.checked); dirty(true); }} />활성 조사 방식</label><div className="ev-actions end"><button className="ev-button primary" disabled={busy || !methodName.trim()} onClick={async () => { if (await save({ type: 'saveMethod', method: { id: methodId || undefined, name: methodName, kind: methodKind, active } }, '조사 방식을 저장했습니다.')) { setMethodId(''); setMethodName(''); setMethodKind('ai'); setActive(true); } }}>조사 방식 저장</button></div></div></Panel></div>;
}

function CaseSettings({ state, month, save, busy, dirty }: Shared) {
  const [examinerId, setExaminerId] = useState(''); const [number, setNumber] = useState(''); const [cpc, setCpc] = useState('');
  return <Panel title="운영상 출원 추가" description="선정 확정 후 필요한 출원을 관리자가 추가할 수 있습니다. 취소는 통계·현황의 출원별 목록에서 처리합니다."><div className="ev-panel-body ev-form-stack"><label>담당 심사관<select value={examinerId} onChange={(event) => { setExaminerId(event.target.value); dirty(true); }}><option value="">담당 심사관 선택</option>{state.users.filter((user) => month.participants.some((entry) => entry.userId === user.id)).map((user) => <option key={user.id} value={user.id}>{user.division} - {user.name}</option>)}</select></label><div className="ev-field-grid"><label>출원번호<input value={number} onChange={(event) => { setNumber(event.target.value); dirty(true); }} placeholder="10-2024-0000000" /></label><label>CPC · 선택<input value={cpc} onChange={(event) => { setCpc(event.target.value); dirty(true); }} /></label></div><div className="ev-actions end"><button className="ev-button primary" disabled={busy || month.closed || !examinerId || !number.trim()} onClick={async () => { if (await save({ type: 'adminAddCase', monthId: month.id, examinerId, row: { applicationNumber: number, cpc } }, '출원을 추가했습니다.')) { setNumber(''); setCpc(''); } }}>출원 등록</button></div></div></Panel>;
}
